import { HttpMethod } from 'aws-cdk-lib/aws-apigatewayv2';

// The backend shape is generated by Amplify from the spread businessFunctions object.
// Keep the route construction here so placeholder operations remain easy to audit.
export function getBusinessRoutes(backend: any) {
  return [
    { path: '/app/subscriptions', method: HttpMethod.GET, integrationId: 'ListSubscriptionsIntegration', lambda: backend.manageSubscriptions.resources.lambda, protected: true },
    { path: '/app/subscriptions/{id}/cancel', method: HttpMethod.POST, integrationId: 'CancelSubscriptionIntegration', lambda: backend.manageSubscriptions.resources.lambda, protected: true },
    { path: '/app/subscriptions/{id}/portal', method: HttpMethod.POST, integrationId: 'SubscriptionPortalIntegration', lambda: backend.manageSubscriptions.resources.lambda, protected: true },
    { path: '/app/admin/catalog', method: HttpMethod.GET, integrationId: 'AdminCatalogIntegration', lambda: backend.stripeCatalog.resources.lambda, protected: true },
    { path: '/app/admin/catalog', method: HttpMethod.POST, integrationId: 'CreateCatalogIntegration', lambda: backend.stripeCatalog.resources.lambda, protected: true },
    { path: '/public/catalog/{businessId}', method: HttpMethod.GET, integrationId: 'PublicCatalogIntegration', lambda: backend.stripeCatalog.resources.lambda, protected: false },
    { path: '/internal/users', method: HttpMethod.POST, integrationId: 'AdminCreateUserIntegration', lambda: backend.adminCreateUser.resources.lambda, protected: true },
    { path: '/internal/platform/status', method: HttpMethod.POST, integrationId: 'UpdatePlatformStatusIntegration', lambda: backend.updatePlatformStatus.resources.lambda, protected: true },
    { path: '/app/admin/projects', method: HttpMethod.POST, integrationId: 'CreateProjectDataIntegration', lambda: backend.createProjectData.resources.lambda, protected: true },
    { path: '/app/projects', method: HttpMethod.GET, integrationId: 'GetProjectDataIntegration', lambda: backend.getProjectData.resources.lambda, protected: true },
    { path: '/app/admin/projects', method: HttpMethod.PUT, integrationId: 'UpdateProjectDataIntegration', lambda: backend.updateProjectData.resources.lambda, protected: true },
    { path: '/app/admin/projects/{id}', method: HttpMethod.DELETE, integrationId: 'DeleteProjectDataIntegration', lambda: backend.deleteProjectData.resources.lambda, protected: true },
    { path: '/public/portfolio/{businessId}', method: HttpMethod.GET, integrationId: 'GetPortfolioDataIntegration', lambda: backend.getPortfolioData.resources.lambda, protected: false },
    { path: '/app/admin/portfolio/{id}', method: HttpMethod.DELETE, integrationId: 'DeletePortfolioDataIntegration', lambda: backend.deletePortfolioData.resources.lambda, protected: true },
    { path: '/app/admin/payments/client/{clientId}', method: HttpMethod.GET, integrationId: 'GetPaymentsByClientIdIntegration', lambda: backend.getPaymentsByClientId.resources.lambda, protected: true },
    { path: '/app/admin/referrals/client/{clientId}', method: HttpMethod.GET, integrationId: 'GetReferralsByClientIdIntegration', lambda: backend.getReferralsByClientId.resources.lambda, protected: true },
    { path: '/app/support/tickets/after/{lastFetched}', method: HttpMethod.GET, integrationId: 'GetTicketsAfterDateIntegration', lambda: backend.getTicketsAfterDate.resources.lambda, protected: true },
    { path: '/app/support/tickets/metadata/{id}', method: HttpMethod.GET, integrationId: 'GetMetadataIntegration', lambda: backend.getMetadata.resources.lambda, protected: true },
    { path: '/app/payments/stripe/session', method: HttpMethod.POST, integrationId: 'CreateStripeSessionIntegration', lambda: backend.createStripeSession.resources.lambda, protected: true },
    { path: '/app/payments/stripe/session/{sessionId}', method: HttpMethod.GET, integrationId: 'GetStripeSessionIntegration', lambda: backend.getStripeSession.resources.lambda, protected: true },
  ];
}
